#include <bits/stdc++.h>
using namespace std;

long long INF = 1e18;
long long total_moves = 0;
vector<int> cache;

int calculate_steps(long long n) {
    if (n == 0) return 0;
    if (n < (long long)cache.size() && cache[n]) return cache[n];

    long long min_diff = INF;
    long long x = 1;
    int steps = 0;

    while (abs(x - n) <= min_diff) {
        min_diff = abs(x - n);
        x = x * 10 + 1;
        steps++;
    }
    x /= 10;

    if (x > n && x / 10) {
        if (n < (long long)cache.size()) {
            return cache[n] = min(steps + calculate_steps(abs(x - n)),
                                   steps - 1 + calculate_steps(abs(x / 10 - n)));
        }
        return min(steps + calculate_steps(abs(x - n)),
                   steps - 1 + calculate_steps(abs(x / 10 - n)));
    }
    if (n < (long long)cache.size()) {
        return cache[n] = steps + calculate_steps(abs(x - n));
    }
    return steps + calculate_steps(abs(x - n));
}

int main() {
    ios_base::sync_with_stdio(false);
    long long n; cin >> n;
    cache.resize(1e7);
    cout << calculate_steps(n);
    return 0;
}
